import { useEffect, useState } from "react"
import { createRoot } from "react-dom/client"

const fakeLoad = () => new Promise((resolve) =>
  setTimeout(() => resolve([
    { id: 1, name: "Party jollof" },
    { id: 2, name: "Egusi + pounded yam" },
    { id: 3, name: "Pepper soup" },
    { id: 4, name: "Zobo (50cl)" },
  ]), 300))

function Menu({ loadMenu }) {
  const [dishes, setDishes] = useState([])
  const [status, setStatus] = useState("loading")

  useEffect(() => {
    loadMenu()
      .then((data) => { setDishes(data); setStatus("ready") })
      .catch(() => setStatus("error"))
  }, [loadMenu])

  useEffect(() => {
    if (status === "ready") document.title = `Menu · ${dishes.length} dishes`
  }, [status, dishes])

  if (status === "loading") return <p className="status">Loading the menu…</p>
  if (status === "error") return <p className="status">Couldn't load the menu.</p>
  return <ul>{dishes.map((d) => <li key={d.id}>{d.name}</li>)}</ul>
}

createRoot(document.getElementById("root")).render(<Menu loadMenu={fakeLoad} />)
